# FinCom Bridge 2.2.2: why the entry fetch finds nothing on NWS144 (05-Oct-2026).
# Read-only: six small requests for ONE voucher each to YOUR Tally (port 9002). Nothing is changed in Tally.
# Run: open PowerShell (not as administrator is fine) with Tally open on GARG SHEKHAR & COMPANY, paste this whole
# file and press Enter. Copy everything it prints and send it to FinCom.
$port = 9002
function Ask($name, $what, $xml) {
  try {
    $r = Invoke-WebRequest -UseBasicParsing -Uri "http://localhost:$port" -Method Post -ContentType 'text/xml;charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes($xml)) -TimeoutSec 20
    $t = $r.Content
    $n = ([regex]::Matches($t, '<VOUCHER[ >]')).Count
    $ids = ([regex]::Matches($t, '<(MASTERID|VOUCHERNUMBER|DATE|VOUCHERTYPENAME)>[^<]*') | ForEach-Object { $_.Value }) -join ' '
    Write-Output ("$name. $what")
    Write-Output ("   vouchers: $n   $ids")
    Write-Output ("   answer starts: " + ($t.Substring(0, [Math]::Min(400, $t.Length)) -replace '\s+',' '))
  } catch { Write-Output ("$name. $what"); Write-Output ("   ERROR: " + $_.Exception.Message) }
  Write-Output ''
}
Ask 'A' 'FinComVoucherByNumber exactly as 2.2.2 sends it (Receipt 212, 05-Oct-2026)' @'
<ENVELOPE><HEADER><VERSION>1</VERSION><TALLYREQUEST>Export</TALLYREQUEST><TYPE>Collection</TYPE><ID>FinComVoucherByNumber</ID></HEADER><BODY><DESC><STATICVARIABLES><SVEXPORTFORMAT>$$SysName:XML</SVEXPORTFORMAT><SVCURRENTCOMPANY>GARG SHEKHAR &amp; COMPANY</SVCURRENTCOMPANY><SVFROMDATE>20261005</SVFROMDATE><SVTODATE>20261005</SVTODATE></STATICVARIABLES><TDL><TDLMESSAGE><COLLECTION NAME="FinComVoucherByNumber" ISMODIFY="No"><TYPE>Voucher</TYPE><FETCH>GUID, MASTERID, ALTERID, DATE, VOUCHERTYPENAME, VOUCHERNUMBER, PARTYLEDGERNAME, NARRATION, ISCANCELLED, ISOPTIONAL, ALLLEDGERENTRIES.LEDGERNAME, ALLLEDGERENTRIES.AMOUNT, ALLLEDGERENTRIES.ISDEEMEDPOSITIVE, ALLLEDGERENTRIES.BILLALLOCATIONS.NAME, ALLLEDGERENTRIES.BILLALLOCATIONS.BILLTYPE, ALLLEDGERENTRIES.BILLALLOCATIONS.AMOUNT, ALLLEDGERENTRIES.BILLALLOCATIONS.BILLCREDITPERIOD</FETCH><FILTERS>FinComVoucherByNumberOnly</FILTERS></COLLECTION><SYSTEM TYPE="Formulae" NAME="FinComVoucherByNumberOnly">$VoucherNumber = &#34;212&#34; AND $VoucherTypeName = &#34;Receipt&#34;</SYSTEM></TDLMESSAGE></TDL></DESC></BODY></ENVELOPE>
'@
